import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class ProfileScreen extends ConsumerWidget{const ProfileScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Profile')),body:ListView(padding:const EdgeInsets.all(16),children:[const CircleAvatar(radius:42,child:Icon(Icons.person_outline,size:48)),const Center(child:Text('Shammah Moyo',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))),const Center(child:Text('shammah@example.com • Harare, Zimbabwe')),const SizedBox(height:16),for(final item in ['Saved items','My submissions','Notifications','Privacy settings','Appearance settings','Help and support','About Zaylo']) ListTile(leading:const Icon(Icons.chevron_right),title:Text(item),onTap:()=>showComingSoon(context,item)),ListTile(leading:const Icon(Icons.logout),title:const Text('Sign out'),onTap:(){ref.read(authProvider.notifier).signOut();context.go('/welcome');})]));}
